    "explanation": "📘 **NCERT Fundamental Concept:**\nDestructive interference occurs when path difference is $\\Delta x_1 = (2n-1)\\frac{\\lambda}{2}$. For constructive interference, the path difference must become an integral multiple of $\\lambda$, i.e., $\\Delta x_2 = n\\lambda$.\n\n⚡ **Step-by-Step Derivation & Calculations:**\n$$\\Delta x_2 - \\Delta x_1 = n\\lambda - (2n-1)\\frac{\\lambda}{2} = \\frac{\\lambda}{2}$$\nThus, increasing the path length by $\\lambda/2$ shifts destructive interference directly to constructive interference.\n\n✓ **Examiner Pro-Tip:**\nShifting between consecutive maximum and minimum requires an additional path difference of $\\lambda/2$ (or phase difference of $\\pi$).",
    "tags": [
      "Errorless Physics",
      "Waves and Sound",
      "Interference of Waves",
      "Interference and Superposition"
    ]
